from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def replace(file,changes):
    p=ROOT/file;s=p.read_text(encoding='utf8')
    for a,b in changes:s=s.replace(a,b)
    p.write_text(s,encoding='utf8')
